package com.runeloot;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("rune-loot")
public interface RuneLootConfig extends Config
{
	enum AnimationDirection
	{
		TOP,
		BOTTOM
	}

	enum TitleAlignment
	{
		LEFT,
		MIDDLE,
		RIGHT
	}

	@ConfigSection(name = "Sources", description = "Which loot sources trigger the popup", position = 0)
	String sourcesSection = "sources";

	@ConfigSection(name = "Filter", description = "Value and tradability filters", position = 1)
	String filterSection = "filter";

	@ConfigSection(name = "Text", description = "Title text for each drop type", position = 2)
	String textSection = "text";

	@ConfigSection(name = "Colors", description = "Popup colors", position = 3)
	String colorsSection = "colors";

	@ConfigSection(name = "Display", description = "Timing and value display", position = 4)
	String displaySection = "display";

	@ConfigSection(name = "Sound", description = "Notification sound settings", position = 5)
	String soundSection = "sound";

	@ConfigSection(name = "Test", description = "Test the popup in-game", position = 6)
	String testSection = "test";

	@ConfigItem(
		keyName = "showNpcDrops",
		name = "NPC Drops",
		description = "Show popup for drops from NPCs and bosses",
		section = "sources",
		position = 0
	)
	default boolean showNpcDrops()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPlayerDrops",
		name = "Player Drops (PvP)",
		description = "Show popup for drops from killed players",
		section = "sources",
		position = 1
	)
	default boolean showPlayerDrops()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRaidLoot",
		name = "Raids",
		description = "Show popup for Chambers of Xeric, Theatre of Blood, Tombs of Amascut, etc.",
		section = "sources",
		position = 2
	)
	default boolean showRaidLoot()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showClueRewards",
		name = "Clue Scroll Rewards",
		description = "Show popup for clue scroll reward caskets",
		section = "sources",
		position = 3
	)
	default boolean showClueRewards()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOtherEvents",
		name = "Other Events",
		description = "Show popup for other event loot (Barrows, minigames, etc.)",
		section = "sources",
		position = 4
	)
	default boolean showOtherEvents()
	{
		return true;
	}

	@ConfigItem(
		keyName = "valueThreshold",
		name = "Value Threshold (gp)",
		description = "Minimum GE value (per item x quantity) to trigger the popup",
		section = "filter",
		position = 0
	)
	default int valueThreshold()
	{
		return 100_000;
	}

	@ConfigItem(
		keyName = "showUntradeable",
		name = "Show Untradeable Drops",
		description = "Show popup for drops that cannot be sold on the Grand Exchange",
		section = "filter",
		position = 1
	)
	default boolean showUntradeable()
	{
		return true;
	}

	@ConfigItem(
		keyName = "excludedItems",
		name = "Excluded Items",
		description = "Comma-separated item names to never show a popup for, e.g. Bull bones, Serafina's diary, The butcher",
		section = "filter",
		position = 2
	)
	default String excludedItems()
	{
		return "";
	}

	@ConfigItem(
		keyName = "tradeableTitle",
		name = "Tradeable Drop Title",
		description = "Title shown when the drop is GE-tradeable",
		section = "text",
		position = 0
	)
	default String tradeableTitle()
	{
		return "Valuable Drop!";
	}

	@ConfigItem(
		keyName = "untradeableTitle",
		name = "Untradeable Drop Title",
		description = "Title shown when the drop is not GE-tradeable",
		section = "text",
		position = 1
	)
	default String untradeableTitle()
	{
		return "Untradeable Drop!";
	}

	@ConfigItem(
		keyName = "titleAlignment",
		name = "Title Alignment",
		description = "Align the title text to the left, middle, or right of the popup",
		section = "text",
		position = 2
	)
	default TitleAlignment titleAlignment()
	{
		return TitleAlignment.MIDDLE;
	}

	@ConfigItem(
		keyName = "tradeableTitleColor",
		name = "Tradeable Title Color",
		description = "Color of the title text for tradeable drops",
		section = "colors",
		position = 0
	)
	default Color tradeableTitleColor()
	{
		return new Color(255, 215, 0);
	}

	@ConfigItem(
		keyName = "untradeableTitleColor",
		name = "Untradeable Title Color",
		description = "Color of the title text for untradeable drops",
		section = "colors",
		position = 1
	)
	default Color untradeableTitleColor()
	{
		return new Color(255, 165, 0);
	}

	@Alpha
	@ConfigItem(
		keyName = "backgroundColor",
		name = "Background Color",
		description = "Background fill color and opacity",
		section = "colors",
		position = 2
	)
	default Color backgroundColor()
	{
		return new Color(62, 45, 19, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "titleBarColor",
		name = "Title Bar Color",
		description = "Title bar fill color and opacity",
		section = "colors",
		position = 3
	)
	default Color titleBarColor()
	{
		return new Color(39, 27, 10, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "borderColor",
		name = "Border Color",
		description = "Color of the popup border",
		section = "colors",
		position = 4
	)
	default Color borderColor()
	{
		return new Color(28, 20, 7, 255);
	}

	@ConfigItem(
		keyName = "valueLowColor",
		name = "Value Color (under 10M)",
		description = "Color of the value text for drops under 10,000,000 gp",
		section = "colors",
		position = 5
	)
	default Color valueLowColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "valueMidColor",
		name = "Value Color (10M - 1B)",
		description = "Color of the value text for drops between 10M and 1B gp",
		section = "colors",
		position = 6
	)
	default Color valueMidColor()
	{
		return new Color(0, 200, 83);
	}

	@ConfigItem(
		keyName = "valueHighColor",
		name = "Value Color (1B+)",
		description = "Color of the value text for drops at or above 1,000,000,000 gp",
		section = "colors",
		position = 7
	)
	default Color valueHighColor()
	{
		return new Color(255, 215, 0);
	}

	@ConfigItem(
		keyName = "displayDuration",
		name = "Display Duration (seconds)",
		description = "How long each popup is fully visible before it exits",
		section = "display",
		position = 0
	)
	@Range(min = 1, max = 30)
	default int displayDuration()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "showValue",
		name = "Show Item Value",
		description = "Display the item's GP value in the popup",
		section = "display",
		position = 1
	)
	default boolean showValue()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showUntradeableValue",
		name = "Show Untradeable Value",
		description = "Show the high-alch value for untradeable drops",
		section = "display",
		position = 2
	)
	default boolean showUntradeableValue()
	{
		return true;
	}

	@ConfigItem(
		keyName = "screenshotEnabled",
		name = "Screenshot on Popup",
		description = "Save a screenshot when the popup fully appears. Saved to .runelite/rune-loot/screenshots/",
		section = "display",
		position = 3
	)
	default boolean screenshotEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showGpSuffix",
		name = "Show 'gp' Suffix",
		description = "Append 'gp' after the value",
		section = "display",
		position = 4
	)
	default boolean showGpSuffix()
	{
		return true;
	}

	@ConfigItem(
		keyName = "abbreviateValue",
		name = "Abbreviate Value",
		description = "Show 15.8M instead of 15,821,990",
		section = "display",
		position = 5
	)
	default boolean abbreviateValue()
	{
		return true;
	}

	@ConfigItem(
		keyName = "animationDirection",
		name = "Animation Direction",
		description = "Expand from the top or bottom of the popup, and collapse back to that edge",
		section = "display",
		position = 6
	)
	default AnimationDirection animationDirection()
	{
		return AnimationDirection.TOP;
	}

	@ConfigItem(
		keyName = "previewLayout",
		name = "Preview Layout",
		description = "Show a silent preview while idle. Hold Alt and drag the center to move, or an edge to resize. Alt-right-click resets the layout.",
		section = "display",
		position = 7
	)
	default boolean previewLayout()
	{
		return false;
	}

	@ConfigItem(
		keyName = "soundEnabled",
		name = "Play Sound on Popup",
		description = "Play a local audio file when a popup appears",
		section = "sound",
		position = 0
	)
	default boolean soundEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "soundFilePath",
		name = "Sound File Path",
		description = "Full path to a custom WAV file. Leave blank to use the built-in sound. MP3 is not supported.",
		section = "sound",
		position = 1
	)
	default String soundFilePath()
	{
		return "";
	}

	@ConfigItem(
		keyName = "soundVolume",
		name = "Volume (dB)",
		description = "Volume adjustment in decibels. 0 = original level, negative = quieter, positive = louder.",
		section = "sound",
		position = 2
	)
	@Range(min = -40, max = 6)
	default int soundVolume()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "testItemName",
		name = "Item Name or ID",
		description = "Item name (e.g. Dragon bones) or numeric item ID to use for the test popup",
		section = "test",
		position = 0
	)
	default String testItemName()
	{
		return "Dragon bones";
	}

	@ConfigItem(
		keyName = "testTrigger",
		name = "Show Test Popup",
		description = "Toggle on to fire a test popup for the item above (auto-resets so you can toggle again)",
		section = "test",
		position = 1
	)
	default boolean testTrigger()
	{
		return false;
	}
}

package com.runeloot;

import java.awt.image.BufferedImage;
import java.time.Instant;
import lombok.Getter;

@Getter
class RuneLootNotification
{
	private final String itemName;
	private final long value;
	private final BufferedImage icon;
	private final boolean geTradeable;
	private final Instant receivedAt;

	RuneLootNotification(String itemName, long value, BufferedImage icon, boolean geTradeable)
	{
		this.itemName = itemName;
		this.value = value;
		this.icon = icon;
		this.geTradeable = geTradeable;
		this.receivedAt = Instant.now();
	}
}

package com.runeloot;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Paint;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.ConcurrentLinkedDeque;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

@Slf4j
class RuneLootOverlay extends Overlay
{
	private static final int PADDING = 8;
	private static final int ANIM_MS = 250;
	private static final int PINCH_W = 4;
	private static final int SLOT_SIZE = 36;

	private static final DateTimeFormatter SCREENSHOT_TS = DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss");

	private enum AnimPhase { ENTER_V, ENTER_H, SHOWING, EXIT_H, EXIT_V }

	private final RuneLootConfig config;
	private final DrawManager drawManager;
	private final ConcurrentLinkedDeque<RuneLootNotification> queue = new ConcurrentLinkedDeque<>();
	private final BufferedImage holderImage;
	private final RuneLootNotification preview = new RuneLootNotification("Layout preview", 100_000, null, true);

	private RuneLootNotification current;
	private AnimPhase phase;
	private Instant phaseStart;

	@Inject
	RuneLootOverlay(RuneLootConfig config, DrawManager drawManager)
	{
		this.config = config;
		this.drawManager = drawManager;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setResizable(true);
		setMinimumSize(64);
		holderImage = loadHolder();
	}

	private static BufferedImage loadHolder()
	{
		try (InputStream is = RuneLootOverlay.class.getResourceAsStream("/com/runeloot/icon_holder.png"))
		{
			if (is == null) return null;
			BufferedImage raw = ImageIO.read(is);
			BufferedImage result = new BufferedImage(raw.getWidth(), raw.getHeight(), BufferedImage.TYPE_INT_ARGB);
			for (int py = 0; py < raw.getHeight(); py++)
			{
				for (int px = 0; px < raw.getWidth(); px++)
				{
					int rgb = raw.getRGB(px, py);
					boolean isPink = ((rgb >> 16) & 0xFF) == 255 && ((rgb >> 8) & 0xFF) == 0 && (rgb & 0xFF) == 255;
					result.setRGB(px, py, isPink ? 0x00000000 : (0xFF000000 | (rgb & 0x00FFFFFF)));
				}
			}
			return result;
		}
		catch (IOException e)
		{
			log.warn("Could not load icon_holder.png", e);
			return null;
		}
	}

	void addNotification(RuneLootNotification notification)
	{
		queue.offer(notification);
	}

	void clearQueue()
	{
		queue.clear();
		current = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (current == null)
		{
			current = queue.poll();
			if (current == null) return renderIdle(graphics);
			startPhase(AnimPhase.ENTER_V);
		}

		long elapsed = Duration.between(phaseStart, Instant.now()).toMillis();
		switch (phase)
		{
			case ENTER_V: if (elapsed >= ANIM_MS) startPhase(AnimPhase.ENTER_H); break;
			case ENTER_H: if (elapsed >= ANIM_MS) startPhase(AnimPhase.SHOWING);  break;
			case SHOWING:  if (elapsed >= config.displayDuration() * 1000L) startPhase(AnimPhase.EXIT_H); break;
			case EXIT_H:  if (elapsed >= ANIM_MS) startPhase(AnimPhase.EXIT_V);  break;
			case EXIT_V:
				if (elapsed >= ANIM_MS)
				{
					current = queue.poll();
					if (current == null) return renderIdle(graphics);
					startPhase(AnimPhase.ENTER_V);
				}
				break;
		}

		return renderNotification(graphics, current, phase);
	}

	private Dimension renderIdle(Graphics2D graphics)
	{
		return config.previewLayout() ? renderNotification(graphics, preview, AnimPhase.SHOWING) : null;
	}

	private void startPhase(AnimPhase next)
	{
		phase = next;
		phaseStart = Instant.now();
		if (next == AnimPhase.SHOWING && config.screenshotEnabled() && current != null)
		{
			final String itemName = current.getItemName();
			drawManager.requestNextFrameListener(image -> saveScreenshot(itemName, image));
		}
	}

	private void saveScreenshot(String itemName, Image image)
	{
		BufferedImage screenshot = ImageUtil.bufferedImageFromImage(image);
		new Thread(() ->
		{
			try
			{
				File dir = new File(RuneLite.RUNELITE_DIR, "rune-loot/screenshots");
				dir.mkdirs();
				String safe = itemName.replaceAll("[^a-zA-Z0-9_\\-]", "_");
				String ts = LocalDateTime.now().format(SCREENSHOT_TS);
				File out = new File(dir, safe + "_" + ts + ".png");
				ImageIO.write(screenshot, "PNG", out);
				log.debug("Rune Loot: screenshot saved to {}", out.getAbsolutePath());
			}
			catch (IOException e)
			{
				log.warn("Rune Loot: failed to save screenshot", e);
			}
		}, "rune-loot-screenshot").start();
	}

	private Dimension renderNotification(Graphics2D graphics, RuneLootNotification n, AnimPhase renderPhase)
	{
		Graphics2D copy = (Graphics2D) graphics.create();
		try
		{
			return drawNotification(copy, n, renderPhase);
		}
		finally
		{
			copy.dispose();
		}
	}

	private Dimension drawNotification(Graphics2D graphics, RuneLootNotification n, AnimPhase renderPhase)
	{
		Font originalFont = graphics.getFont();
		Font boldFont = originalFont.deriveFont(Font.BOLD);
		FontMetrics fm = graphics.getFontMetrics(originalFont);
		FontMetrics boldFm = graphics.getFontMetrics(boldFont);

		String title = n.isGeTradeable() ? config.tradeableTitle() : config.untradeableTitle();
		String name = n.getItemName();
		String valueText = config.showValue() && (n.isGeTradeable() || config.showUntradeableValue())
			? formatValue(n.getValue()) + (config.showGpSuffix() ? " gp" : "")
			: null;

		int textBlockW = valueText != null
			? Math.max(fm.stringWidth(name), fm.stringWidth(valueText))
			: fm.stringWidth(name);

		int titleBarH = boldFm.getHeight() + PADDING * 2;
		int contentW = PADDING + SLOT_SIZE + PADDING + textBlockW + PADDING;
		int fullW = Math.max(boldFm.stringWidth(title) + PADDING * 2, contentW);

		int textLines = 1 + (valueText != null ? 1 : 0);
		int textH = textLines * fm.getHeight();
		int contentH = Math.max(SLOT_SIZE, textH) + PADDING * 2;
		int fullH = titleBarH + contentH;

		Dimension preferred = getPreferredSize();
		if (preferred != null)
		{
			// Resize the panel, not the pixel font or item sprite. Keep the full price readable.
			int minimumTextWidth = fm.stringWidth(valueText != null ? valueText : "...");
			int minimumWidth = PADDING * 3 + SLOT_SIZE + minimumTextWidth;
			fullW = Math.max(Math.max(getMinimumSize(), minimumWidth), preferred.width);
			fullH = Math.max(fullH, preferred.height);
			contentH = fullH - titleBarH;
		}
		Dimension size = new Dimension(fullW, fullH);
		title = fitText(title, boldFm, fullW - PADDING * 2);
		name = fitText(name, fm, fullW - PADDING * 3 - SLOT_SIZE);

		long elapsed = renderPhase == AnimPhase.SHOWING ? 0 : Duration.between(phaseStart, Instant.now()).toMillis();
		double t = Math.min(1.0, elapsed / (double) ANIM_MS);
		double easeOut = 1.0 - Math.pow(1.0 - t, 3);
		double easeIn  = Math.pow(t, 3);

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		switch (renderPhase)
		{
			case ENTER_V:
			{
				int barH = Math.max(1, (int)(fullH * easeOut));
				graphics.setColor(config.borderColor());
				int barY = config.animationDirection() == RuneLootConfig.AnimationDirection.BOTTOM ? fullH - barH : 0;
				graphics.fillRect((fullW - PINCH_W) / 2, barY, PINCH_W, barH);
				break;
			}
			case ENTER_H:
			{
				int w = Math.max(1, PINCH_W + (int)((fullW - PINCH_W) * easeOut));
				Shape saved = graphics.getClip();
				graphics.clipRect((fullW - w) / 2, 0, w, fullH);
				drawContent(graphics, n, boldFont, fm, boldFm, title, name, valueText, fullW, fullH, titleBarH, contentH);
				drawBeveledBorder(graphics, config.borderColor(), fullW, fullH);
				graphics.setClip(saved);
				break;
			}
			case SHOWING:
			{
				drawContent(graphics, n, boldFont, fm, boldFm, title, name, valueText, fullW, fullH, titleBarH, contentH);
				drawBeveledBorder(graphics, config.borderColor(), fullW, fullH);
				break;
			}
			case EXIT_H:
			{
				int w = Math.max(PINCH_W, fullW - (int)((fullW - PINCH_W) * easeIn));
				Shape saved = graphics.getClip();
				graphics.clipRect((fullW - w) / 2, 0, w, fullH);
				drawContent(graphics, n, boldFont, fm, boldFm, title, name, valueText, fullW, fullH, titleBarH, contentH);
				drawBeveledBorder(graphics, config.borderColor(), fullW, fullH);
				graphics.setClip(saved);
				break;
			}
			case EXIT_V:
			{
				int barH = Math.max(1, fullH - (int)(fullH * easeIn));
				graphics.setColor(config.borderColor());
				int barY = config.animationDirection() == RuneLootConfig.AnimationDirection.BOTTOM ? fullH - barH : 0;
				graphics.fillRect((fullW - PINCH_W) / 2, barY, PINCH_W, barH);
				break;
			}
		}

		return size;
	}

	private static String fitText(String text, FontMetrics metrics, int width)
	{
		if (metrics.stringWidth(text) <= width) return text;
		String suffix = "...";
		if (metrics.stringWidth(suffix) > width) return "";
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end) + suffix) > width)
		{
			end = text.offsetByCodePoints(end, -1);
		}
		return text.substring(0, end) + suffix;
	}

	private void drawContent(
		Graphics2D g, RuneLootNotification n,
		Font boldFont, FontMetrics fm, FontMetrics boldFm,
		String title, String name, String valueText,
		int fullW, int fullH, int titleBarH, int contentH)
	{
		Font originalFont = g.getFont();

		g.setColor(config.backgroundColor());
		g.fillRect(0, 0, fullW, fullH);

		g.setColor(config.titleBarColor());
		g.fillRect(0, 0, fullW, titleBarH);

		applyVignette(g, 0, titleBarH, fullW, contentH);

		g.setColor(config.borderColor());
		g.drawLine(2, titleBarH, fullW - 3, titleBarH);

		g.setFont(boldFont);
		g.setColor(n.isGeTradeable() ? config.tradeableTitleColor() : config.untradeableTitleColor());
		int titleWidth = boldFm.stringWidth(title);
		int titleX;
		switch (config.titleAlignment())
		{
			case LEFT:
				titleX = PADDING;
				break;
			case RIGHT:
				titleX = fullW - titleWidth - PADDING;
				break;
			default:
				titleX = (fullW - titleWidth) / 2;
		}
		int titleY = (titleBarH - boldFm.getHeight()) / 2 + boldFm.getAscent();
		g.drawString(title, titleX, titleY);
		g.setFont(originalFont);

		int slotY = titleBarH + (contentH - SLOT_SIZE) / 2;
		drawItemSlot(g, n.getIcon(), PADDING, slotY);

		int textLines = 1 + (valueText != null ? 1 : 0);
		int textH = textLines * fm.getHeight();
		int textX = PADDING + SLOT_SIZE + PADDING;
		int textY = titleBarH + (contentH - textH) / 2 + fm.getAscent();

		g.setColor(Color.WHITE);
		g.drawString(name, textX, textY);

		if (valueText != null)
		{
			g.setColor(getValueColor(n.getValue()));
			g.drawString(valueText, textX, textY + fm.getHeight());
		}
	}

	private void drawItemSlot(Graphics2D g, BufferedImage icon, int x, int y)
	{
		if (holderImage != null)
		{
			g.drawImage(holderImage, x, y, SLOT_SIZE, SLOT_SIZE, null);
		}
		else
		{
			g.setColor(new Color(61, 59, 54));
			g.fillRect(x, y, SLOT_SIZE, SLOT_SIZE);
			g.setColor(new Color(108, 101, 90));
			g.drawLine(x, y, x + SLOT_SIZE - 1, y);
			g.drawLine(x, y, x, y + SLOT_SIZE - 1);
			g.setColor(new Color(26, 24, 20));
			g.drawLine(x, y + SLOT_SIZE - 1, x + SLOT_SIZE - 1, y + SLOT_SIZE - 1);
			g.drawLine(x + SLOT_SIZE - 1, y, x + SLOT_SIZE - 1, y + SLOT_SIZE - 1);
		}

		if (icon != null)
		{
			int ix = x + (SLOT_SIZE - icon.getWidth()) / 2 + 2;
			int iy = y + (SLOT_SIZE - icon.getHeight()) / 2;
			g.drawImage(icon, ix, iy, null);
		}
	}

	private static void drawBeveledBorder(Graphics2D g, Color base, int w, int h)
	{
		g.setColor(darker(base, 2));
		g.drawRect(0, 0, w - 1, h - 1);

		g.setColor(base);
		g.drawRect(1, 1, w - 3, h - 3);
		g.drawRect(2, 2, w - 5, h - 5);

		g.setColor(lighter(base));
		g.drawLine(3, 3, w - 4, 3);
		g.drawLine(3, 4, 3, h - 4);

		g.setColor(darker(base, 1));
		g.drawLine(4, h - 4, w - 4, h - 4);
		g.drawLine(w - 4, 4, w - 4, h - 4);
	}

	private static void applyVignette(Graphics2D g, int x, int y, int w, int h)
	{
		float radius = Math.max(w, h) * 0.65f;
		RadialGradientPaint vignette = new RadialGradientPaint(
			x + w / 2f, y + h / 2f, radius,
			new float[]{ 0.2f, 1.0f },
			new Color[]{ new Color(0, 0, 0, 0), new Color(0, 0, 0, 110) }
		);
		Paint saved = g.getPaint();
		g.setPaint(vignette);
		g.fillRect(x, y, w, h);
		g.setPaint(saved);
	}

	private static Color lighter(Color c)
	{
		return new Color(
			Math.min(255, c.getRed() + 65),
			Math.min(255, c.getGreen() + 50),
			Math.min(255, c.getBlue() + 25),
			c.getAlpha()
		);
	}

	private static Color darker(Color c, int passes)
	{
		Color r = c;
		for (int i = 0; i < passes; i++)
		{
			r = new Color(
				Math.max(0, r.getRed() - 50),
				Math.max(0, r.getGreen() - 40),
				Math.max(0, r.getBlue() - 20),
				r.getAlpha()
			);
		}
		return r;
	}

	private String formatValue(long value)
	{
		if (!config.abbreviateValue())
		{
			return String.format("%,d", value);
		}
		if (value >= 1_000_000_000) return String.format("%.1fB", value / 1_000_000_000.0);
		if (value >= 1_000_000)     return String.format("%.1fM", value / 1_000_000.0);
		if (value >= 1_000)         return String.format("%.1fK", value / 1_000.0);
		return String.valueOf(value);
	}

	private Color getValueColor(long value)
	{
		if (value >= 1_000_000_000) return config.valueHighColor();
		if (value >= 10_000_000)    return config.valueMidColor();
		return config.valueLowColor();
	}
}

package com.runeloot;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.http.api.item.ItemPrice;

@Slf4j
@PluginDescriptor(
	name = "Rune Loot",
	description = "Shows an animated popup for drops at or above a configurable GP value threshold",
	tags = {"loot", "drop", "notification", "value", "popup", "rune"}
)
public class RuneLootPlugin extends Plugin
{
	@Inject private RuneLootConfig config;
	@Inject private RuneLootOverlay overlay;
	@Inject private OverlayManager overlayManager;
	@Inject private ItemManager itemManager;
	@Inject private ClientThread clientThread;
	@Inject private RuneLootSoundPlayer soundPlayer;
	@Inject private ConfigManager configManager;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		log.debug("Rune Loot started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.clearQueue();
		log.debug("Rune Loot stopped");
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		switch (event.getType())
		{
			case NPC:
			case PICKPOCKET:
				if (!config.showNpcDrops()) return;
				break;
			case PLAYER:
				if (!config.showPlayerDrops()) return;
				break;
			case EVENT:
			{
				String name = event.getName().toLowerCase(Locale.ROOT);
				boolean isRaid = name.contains("chambers") || name.contains("theatre")
					|| name.contains("tombs") || name.contains("raids");
				boolean isClue = name.contains("casket") || name.contains("clue");
				if (isRaid && !config.showRaidLoot()) return;
				if (isClue && !config.showClueRewards()) return;
				if (!isRaid && !isClue && !config.showOtherEvents()) return;
				break;
			}
			default:
				return;
		}
		checkItems(event.getItems());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"rune-loot".equals(event.getGroup())) return;
		if ("testTrigger".equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			configManager.setConfiguration("rune-loot", "testTrigger", false);
			String name = config.testItemName();
			if (name != null && !name.isEmpty())
			{
				clientThread.invokeLater(() -> fireTestNotification(name));
			}
		}
	}

	private void fireTestNotification(String input)
	{
		String trimmed = input.trim();
		int id;

		try
		{
			id = Integer.parseInt(trimmed);
		}
		catch (NumberFormatException ignored)
		{
			List<ItemPrice> results = itemManager.search(trimmed);
			if (results.isEmpty())
			{
				log.debug("No item found for test input: {}", trimmed);
				return;
			}
			id = results.get(0).getId();
		}

		var comp = itemManager.getItemComposition(id);
		long gePrice = itemManager.getItemPrice(id);
		boolean geTradeable = comp.isGeTradeable() || gePrice > 0;
		long value = gePrice > 0 ? gePrice : comp.getHaPrice();
		queueNotification(comp.getName(), value, itemManager.getImage(id, 1, comp.isStackable()), geTradeable);
	}

	private void checkItems(Collection<ItemStack> items)
	{
		for (ItemStack item : items)
		{
			var comp = itemManager.getItemComposition(item.getId());

			if (isExcluded(comp.getName())) continue;

			long gePrice = itemManager.getItemPrice(item.getId());

			boolean geTradeable = comp.isGeTradeable() || gePrice > 0;

			if (!geTradeable && !config.showUntradeable()) continue;

			long unitValue = gePrice > 0 ? gePrice : comp.getHaPrice();
			long totalValue = unitValue * item.getQuantity();

			if (geTradeable && totalValue < config.valueThreshold()) continue;

			queueNotification(comp.getName(), totalValue,
				itemManager.getImage(item.getId(), item.getQuantity(), comp.isStackable()),
				geTradeable);
		}
	}

	private void queueNotification(String name, long value, BufferedImage icon, boolean geTradeable)
	{
		overlay.addNotification(new RuneLootNotification(cleanName(name), value, icon, geTradeable));
		soundPlayer.playAsync();
	}

	private static String cleanName(String name)
	{
		return name.replaceAll("\\s*\\(Members'?\\)", "").trim();
	}

	private boolean isExcluded(String name)
	{
		String excluded = config.excludedItems();
		if (excluded == null || excluded.isEmpty()) return false;

		String cleaned = cleanName(name);
		for (String token : excluded.split(","))
		{
			if (token.trim().equalsIgnoreCase(cleaned)) return true;
		}
		return false;
	}

	@Provides
	RuneLootConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RuneLootConfig.class);
	}
}

package com.runeloot;

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

@Slf4j
class RuneLootSoundPlayer
{
	private final RuneLootConfig config;

	@Inject
	RuneLootSoundPlayer(RuneLootConfig config)
	{
		this.config = config;
	}

	void playAsync()
	{
		if (!config.soundEnabled()) return;

		String path = config.soundFilePath();
		File file = (path != null && !path.trim().isEmpty()) ? new File(path.trim()) : null;

		if (file != null && file.exists())
		{
			new Thread(() -> playFile(file), "rune-loot-sound").start();
		}
		else
		{
			if (file != null)
			{
				log.warn("Rune Loot: sound file not found at '{}', using built-in sound.", path);
			}
			new Thread(this::playBundled, "rune-loot-sound").start();
		}
	}

	private void playFile(File file)
	{
		try
		{
			new AudioPlayer().play(file, (float) config.soundVolume());
		}
		catch (Exception e)
		{
			log.warn("Rune Loot: failed to play sound file '{}'", file.getName(), e);
		}
	}

	private void playBundled()
	{
		try (InputStream is = RuneLootSoundPlayer.class.getResourceAsStream("/com/runeloot/notification.wav"))
		{
			if (is == null)
			{
				log.warn("Rune Loot: bundled notification.wav not found in resources.");
				return;
			}
			byte[] bytes = is.readAllBytes();
			new AudioPlayer().play(new ByteArrayInputStream(bytes), (float) config.soundVolume());
		}
		catch (Exception e)
		{
			log.warn("Rune Loot: failed to play bundled sound", e);
		}
	}
}

